 "content": "from collections import Counter

def transform(grid):
    # Marker pattern is the small multi-cell object. Replicate the pattern
    # translated over background cells at the positions of matching empty motifs.
    h,w=len(grid),len(grid[0]); cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    marker=min((v for v in cnt if v!=bg), key=lambda x:cnt[x])
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker}
    # Use connected components; choose the component with most marker cells.
    unseen=set(pts); comps=[]
    while unseen:
        stack=[unseen.pop()]; comp=set(stack)
        while stack:
            r,c=stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen: unseen.remove(p); comp.add(p); stack.append(p)
        comps.append(comp)
    pattern=max(comps,key=len)
    out=[row[:] for row in grid]
    # The motif copies into exact background-only translated placements.
    for dr in range(-h,h):
      for dc in range(-w,w):
        if dr==dc==0: continue
        translated={(r+dr,c+dc) for r,c in pattern}
        if all(0<=r<h and 0<=c<w and grid[r][c]==bg for r,c in translated):
            for r,c in translated: out[r][c]=marker
    return out

